/* StayQuest - Travel Platform Styles */
/* Brand: #003B95 (primary navy), #006CE4 (accent blue), #FFB700 (highlight gold) */

:root {
  --primary: #003B95;
  --primary-dark: #002a6b;
  --accent: #006CE4;
  --accent-light: #e6f0ff;
  --highlight: #FFB700;
  --highlight-dark: #e6a500;
  --white: #ffffff;
  --gray-50: #f8f9fa;
  --gray-100: #f1f3f5;
  --gray-200: #e9ecef;
  --gray-300: #dee2e6;
  --gray-400: #adb5bd;
  --gray-500: #868e96;
  --gray-600: #495057;
  --gray-700: #343a40;
  --gray-800: #212529;
  --success: #28a745;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --max-width: 1200px;
  --header-height: 64px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--primary); }

img { max-width: 100%; display: block; }

/* Utility */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.section { padding: 64px 0; }
.section-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--gray-800);
  margin-bottom: 8px;
}
.section-subtitle {
  font-size: 1rem;
  color: var(--gray-500);
  margin-bottom: 32px;
}

/* Header */
.header {
  background: var(--primary);
  color: var(--white);
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: var(--shadow-md);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
}
.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.5px;
}
.logo span { color: var(--highlight); }
.nav { display: flex; gap: 4px; }
.nav a {
  color: rgba(255,255,255,0.85);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius-md);
  transition: all 0.2s;
  white-space: nowrap;
}
.nav a:hover, .nav a.active {
  color: var(--white);
  background: rgba(255,255,255,0.12);
}
.nav a.active { background: rgba(255,255,255,0.18); font-weight: 600; }

/* Hero */
.hero {
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  color: var(--white);
  padding: 56px 0 72px;
}
.hero-inner { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.hero-title { font-size: 2.5rem; font-weight: 800; margin-bottom: 8px; letter-spacing: -0.5px; }
.hero-subtitle { font-size: 1.125rem; opacity: 0.9; margin-bottom: 32px; }

/* Search Form */
.search-form {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-lg);
  color: var(--gray-800);
}
.search-row { display: flex; gap: 12px; flex-wrap: wrap; align-items: flex-end; }
.search-field { flex: 1; min-width: 180px; }
.search-field label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--gray-600);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.search-field input,
.search-field select {
  width: 100%;
  padding: 12px 14px;
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--gray-800);
  background: var(--white);
  transition: border-color 0.2s, box-shadow 0.2s;
}
.search-field input:focus,
.search-field select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(0,108,228,0.1);
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}
.btn-primary {
  background: var(--highlight);
  color: var(--gray-800);
}
.btn-primary:hover { background: var(--highlight-dark); transform: translateY(-1px); }
.btn-secondary {
  background: var(--accent);
  color: var(--white);
}
.btn-secondary:hover { background: var(--primary); }
.btn-outline {
  background: transparent;
  color: var(--accent);
  border: 1.5px solid var(--accent);
}
.btn-outline:hover { background: var(--accent-light); }
.search-btn { padding: 12px 36px; font-size: 1rem; }

.search-extras {
  display: flex;
  gap: 20px;
  margin-top: 16px;
  flex-wrap: wrap;
}
.checkbox-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: var(--gray-600);
  cursor: pointer;
}
.checkbox-label input { width: 18px; height: 18px; accent-color: var(--accent); }

/* Radio group for packages */
.radio-group { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 20px; }
.radio-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9375rem;
  cursor: pointer;
  padding: 8px 12px;
  border-radius: var(--radius-md);
  border: 1.5px solid var(--gray-200);
  transition: all 0.2s;
}
.radio-label:hover { border-color: var(--accent); }
.radio-label input { accent-color: var(--accent); }
.radio-label:has(input:checked) { border-color: var(--accent); background: var(--accent-light); }

/* Trust Badges */
.trust-badges {
  background: var(--gray-50);
  padding: 40px 0;
}
.trust-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
}
.trust-item {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.trust-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--accent);
  font-size: 1.25rem;
}
.trust-text h4 { font-size: 0.9375rem; font-weight: 700; color: var(--gray-800); margin-bottom: 2px; }
.trust-text p { font-size: 0.8125rem; color: var(--gray-500); line-height: 1.5; }

/* Cards */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.2s;
}
.card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.card-img {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: linear-gradient(135deg, var(--gray-200), var(--gray-300));
}
.card-body { padding: 16px; }
.card-title { font-size: 1rem; font-weight: 700; color: var(--gray-800); margin-bottom: 4px; }
.card-meta { font-size: 0.8125rem; color: var(--gray-500); margin-bottom: 8px; }
.card-rating {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8125rem;
  margin-bottom: 8px;
}
.rating-badge {
  background: var(--primary);
  color: var(--white);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 0.75rem;
}
.rating-text { color: var(--gray-600); font-weight: 500; }
.reviews { color: var(--gray-400); }
.card-price { font-size: 1.125rem; font-weight: 700; color: var(--gray-800); }
.card-price .original {
  text-decoration: line-through;
  color: var(--gray-400);
  font-weight: 500;
  margin-right: 6px;
  font-size: 0.9375rem;
}
.card-price .sale { color: var(--primary); }

/* Offers */
.offers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
}
.offer-card {
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  overflow: hidden;
}
.offer-card.alt {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
}
.offer-card h3 { font-size: 1.375rem; font-weight: 700; margin-bottom: 8px; }
.offer-card p { opacity: 0.9; margin-bottom: 20px; font-size: 0.9375rem; }
.offer-card .btn { background: var(--highlight); color: var(--gray-800); }
.offer-card .btn:hover { background: var(--highlight-dark); }

/* Property Types */
.property-types {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.property-chip {
  padding: 10px 18px;
  border-radius: 100px;
  background: var(--gray-100);
  color: var(--gray-700);
  font-size: 0.875rem;
  font-weight: 500;
  transition: all 0.2s;
  cursor: pointer;
  border: 1.5px solid transparent;
}
.property-chip:hover {
  background: var(--accent-light);
  color: var(--accent);
  border-color: var(--accent);
}

/* Tabs */
.tabs-nav {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  margin-bottom: 24px;
  border-bottom: 2px solid var(--gray-200);
  padding-bottom: 2px;
}
.tab-btn {
  padding: 10px 18px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-500);
  background: none;
  border: none;
  cursor: pointer;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  transition: all 0.2s;
  white-space: nowrap;
}
.tab-btn:hover { color: var(--accent); background: var(--accent-light); }
.tab-btn.active {
  color: var(--accent);
  background: var(--accent-light);
  box-shadow: inset 0 -2px 0 var(--accent);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fadeIn 0.3s ease; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

/* Destination Cards */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 20px;
}
.dest-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  cursor: pointer;
  transition: all 0.2s;
}
.dest-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.dest-card .card-img { aspect-ratio: 4/3; }
.dest-card .card-body { padding: 14px; }
.dest-card .card-title { font-size: 0.9375rem; }
.dest-card .card-meta { font-size: 0.75rem; margin-bottom: 0; }

/* Carousel */
.carousel-wrap { position: relative; }
.carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: 4px;
  margin: -4px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.carousel::-webkit-scrollbar { display: none; }
.carousel .card {
  flex: 0 0 300px;
  scroll-snap-align: start;
}
.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  font-size: 1.125rem;
  color: var(--gray-700);
  transition: all 0.2s;
}
.carousel-arrow:hover { background: var(--accent); color: var(--white); border-color: var(--accent); }
.carousel-arrow.prev { left: -20px; }
.carousel-arrow.next { right: -20px; }

/* Weekend Deals */
.deal-card { display: flex; gap: 16px; padding: 16px; }
.deal-card .card-img { width: 140px; flex-shrink: 0; border-radius: var(--radius-md); aspect-ratio: 1; }
.deal-card .card-body { padding: 0; flex: 1; }
.deal-duration {
  display: inline-block;
  padding: 2px 10px;
  background: var(--accent-light);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 100px;
  margin-bottom: 8px;
}

/* Loyalty CTA */
.loyalty-section {
  background: linear-gradient(135deg, var(--accent-light) 0%, #fff 100%);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
}
.loyalty-section h3 { font-size: 1.5rem; font-weight: 700; margin-bottom: 4px; }
.loyalty-section .sub { color: var(--accent); font-weight: 600; font-size: 0.9375rem; margin-bottom: 12px; }
.loyalty-section p { color: var(--gray-500); max-width: 480px; margin: 0 auto 24px; }
.loyalty-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }

/* Popular Links */
.popular-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.popular-tags a {
  padding: 8px 16px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  color: var(--gray-700);
  transition: all 0.2s;
}
.popular-tags a:hover { background: var(--accent-light); color: var(--accent); }

/* FAQ */
.faq-item {
  border-bottom: 1px solid var(--gray-200);
}
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 0;
  background: none;
  border: none;
  font-size: 1rem;
  font-weight: 600;
  color: var(--gray-800);
  cursor: pointer;
  text-align: left;
}
.faq-question:hover { color: var(--accent); }
.faq-question .icon { transition: transform 0.3s; font-size: 0.875rem; }
.faq-item.open .faq-question .icon { transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 20px;
}
.faq-answer p { color: var(--gray-500); font-size: 0.9375rem; line-height: 1.7; }

/* Rental Companies */
.company-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  justify-content: center;
  align-items: center;
}
.company-item {
  padding: 16px 28px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-weight: 700;
  color: var(--gray-700);
  transition: all 0.2s;
}
.company-item:hover { border-color: var(--accent); color: var(--accent); transform: translateY(-2px); }

/* Attractions */
.activity-card {
  display: flex;
  gap: 16px;
  padding: 16px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  transition: all 0.2s;
}
.activity-card:hover { box-shadow: var(--shadow-md); }
.activity-card .card-img { width: 100px; height: 100px; border-radius: var(--radius-md); flex-shrink: 0; }
.activity-card .card-body { padding: 0; }

/* Footer */
.footer {
  background: var(--gray-800);
  color: var(--gray-400);
  padding: 56px 0 32px;
  font-size: 0.875rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 32px;
  margin-bottom: 40px;
}
.footer-col h4 {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.footer-col a {
  display: block;
  color: var(--gray-400);
  margin-bottom: 10px;
  transition: color 0.2s;
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--gray-700);
  padding-top: 24px;
  text-align: center;
  color: var(--gray-500);
  font-size: 0.8125rem;
}

/* Responsive */
@media (max-width: 768px) {
  .header-inner { flex-wrap: wrap; height: auto; padding: 12px 16px; }
  .nav { width: 100%; margin-top: 8px; overflow-x: auto; }
  .hero-title { font-size: 1.75rem; }
  .search-row { flex-direction: column; }
  .search-field { min-width: 100%; }
  .carousel .card { flex: 0 0 260px; }
  .carousel-arrow { display: none; }
  .deal-card { flex-direction: column; }
  .deal-card .card-img { width: 100%; aspect-ratio: 16/10; }
  .section { padding: 40px 0; }
  .loyalty-section { padding: 32px 20px; }
}

/* Utility classes */
.text-center { text-align: center; }
.mt-1 { margin-top: 8px; }
.mt-2 { margin-top: 16px; }
.mt-3 { margin-top: 24px; }
.mb-1 { margin-bottom: 8px; }
.mb-2 { margin-bottom: 16px; }
.mb-3 { margin-bottom: 24px; }
.flex { display: flex; }
.gap-2 { gap: 16px; }
.gap-3 { gap: 24px; }
.wrap { flex-wrap: wrap; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }

// StayQuest - Main JavaScript

document.addEventListener('DOMContentLoaded', () => {
  initTabs();
  initCarousels();
  initFAQ();
  initSearchForms();
});

// Tabs
function initTabs() {
  document.querySelectorAll('.tabs-nav').forEach(nav => {
    const buttons = nav.querySelectorAll('.tab-btn');
    const panels = nav.closest('.tabs-container')?.querySelectorAll('.tab-panel');
    if (!panels) return;

    buttons.forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.dataset.tab;
        buttons.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        panels.forEach(p => {
          p.classList.toggle('active', p.dataset.panel === target);
        });
      });
    });
  });
}

// Carousels
function initCarousels() {
  document.querySelectorAll('.carousel-wrap').forEach(wrap => {
    const carousel = wrap.querySelector('.carousel');
    const prev = wrap.querySelector('.carousel-arrow.prev');
    const next = wrap.querySelector('.carousel-arrow.next');
    if (!carousel) return;

    const scrollAmount = 320;
    if (prev) {
      prev.addEventListener('click', () => {
        carousel.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
      });
    }
    if (next) {
      next.addEventListener('click', () => {
        carousel.scrollBy({ left: scrollAmount, behavior: 'smooth' });
      });
    }
  });
}

// FAQ Accordion
function initFAQ() {
  document.querySelectorAll('.faq-item').forEach(item => {
    const question = item.querySelector('.faq-question');
    if (!question) return;
    question.addEventListener('click', () => {
      const isOpen = item.classList.contains('open');
      // Close all siblings in same FAQ container
      const container = item.closest('.faq-list');
      if (container) {
        container.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
      }
      if (!isOpen) {
        item.classList.add('open');
      }
    });
  });
}

// Search Forms (basic validation)
function initSearchForms() {
  document.querySelectorAll('.search-form form').forEach(form => {
    form.addEventListener('submit', e => {
      e.preventDefault();
      const destination = form.querySelector('[name="destination"]')?.value.trim();
      if (!destination) {
        alert('Please enter a destination');
        return;
      }
      // Simulate search
      const btn = form.querySelector('button[type="submit"]');
      const originalText = btn.innerHTML;
      btn.innerHTML = 'Searching...';
      btn.disabled = true;
      setTimeout(() => {
        btn.innerHTML = originalText;
        btn.disabled = false;
        alert(`Searching for stays in ${destination}...`);
      }, 800);
    });
  });
}
